// Generated by scripts/measure-font.js: Fraunces 500 advance widths in 1/1000 em
// for ASCII 32..126. Do not edit by hand.
const ASCII = [221,315,354,655,597,760,753,168,354,354,624,558,267,413,256,494,662,459,606,552,612,576,605,517,599,609,261,273,515,558,515,514,901,724,694,700,790,653,604,761,840,394,491,776,623,912,775,796,681,796,733,599,686,747,710,1046,728,686,640,336,494,342,480,483,240,551,601,516,613,527,381,568,632,309,309,605,312,948,632,590,616,601,465,478,376,618,555,823,541,562,483,395,274,395,637];
const EXTRA = {"’":222,"‘":224,"“":440,"”":455,"…":879,"—":830,"–":525,"·":282,"é":527,"è":527,"ê":527,"á":551,"à":551,"â":551,"í":308,"ó":590,"ö":590,"ü":618,"ñ":632,"ç":516,"É":653};
const FALLBACK = 560; // accented letters and other scripts
const WIDE = 1000; // emoji and other wide symbols

export function charWidthEm(ch) {
  const c = ch.codePointAt(0);
  if (c >= 32 && c < 127) return ASCII[c - 32] / 1000;
  if (ch in EXTRA) return EXTRA[ch] / 1000;
  if (c > 0xffff || (c >= 0x2600 && c <= 0x27bf)) return WIDE / 1000;
  return FALLBACK / 1000;
}

/** Width of a string in em at Fraunces 500, ignoring kerning. */
export function textWidthEm(text) {
  let w = 0;
  for (const ch of text) w += charWidthEm(ch);
  return w;
}
